package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;

/**
 * A claim a person has on a sheet. {@code id} is null until the claim is first saved; {@code number}
 * is null unless the claim has been opened (a draft has none; a voided claim keeps it). {@code due} is the
 * due fixed when the claim was settled, or null while it is live (not settled, or settled with no rate).
 * {@code openedBy} is the user who opened the claim, or null while it is a draft. {@code stated} is whether
 * its person's last statement bound it to a figure, {@code statedDue} (null: n/a) — it then shows and totals
 * that figure, not its live one. {@code corrects} is, for a correction, the number of the claim it corrects (null:
 * not a correction).
 */
public record Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
        ClaimStatus status, Integer number, BigDecimal due, String openedBy, boolean stated, BigDecimal statedDue,
        Integer corrects) {

    /** The same claim with another status, number, fixed due and opener. */
    public Claim withStatus(ClaimStatus next, Integer nextNumber, BigDecimal nextDue, String nextOpenedBy) {
        return new Claim(id, sheetId, personId, amount, date, note, next, nextNumber, nextDue, nextOpenedBy, stated,
                statedDue, corrects);
    }

    /** Whether the claim is a correction: a negative amount naming the settled claim it corrects. */
    public boolean correction() {
        return corrects != null;
    }

    /** Whether the claim counts toward the totals: only OPEN and SETTLED claims do. */
    public boolean counts() {
        return status == ClaimStatus.OPEN || status == ClaimStatus.SETTLED;
    }

    /** Whether the claim counts toward the live totals when its person is held or not: a held person's open claims do not. */
    public boolean counts(boolean held) {
        return status == ClaimStatus.SETTLED || (status == ClaimStatus.OPEN && !held);
    }

    /**
     * The claim's figure (null: n/a): the due fixed when it was settled, else the figure its statement bound
     * it to, else its amount at the given live rate (null: none), at least the sheet's floor — a correction has
     * no floor.
     */
    public BigDecimal figure(BigDecimal liveRate, BigDecimal floor) {
        if (due != null) {
            return due;
        }
        if (stated) {
            return statedDue;
        }
        return correction() ? due(amount, liveRate) : due(amount, liveRate, floor);
    }

    /**
     * The claim's due (null: n/a): its {@link #figure figure}, plus the late charge on it while it is overdue. A
     * settled claim's fixed due already has the charge frozen in.
     */
    public BigDecimal due(BigDecimal liveRate, BigDecimal floor, LateCharge late) {
        BigDecimal figure = figure(liveRate, floor);
        return due != null || figure == null ? figure : figure.add(late.on(this, figure));
    }

    /** An amount times a percent rate, divided by 100, rounded half to even to two decimals; null with no rate. */
    public static BigDecimal due(BigDecimal amount, BigDecimal rate) {
        return rate == null ? null : amount.multiply(rate).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
    }

    /** A live due: {@link #due(BigDecimal, BigDecimal)}, raised to the floor; null with no rate. */
    public static BigDecimal due(BigDecimal amount, BigDecimal rate, BigDecimal floor) {
        BigDecimal due = due(amount, rate);
        return due == null || due.compareTo(floor) >= 0 ? due : floor.setScale(2);
    }

    /** The audit field for the claim's number, " number=<n>", or "" when it has none. */
    public static String auditNumber(Integer number) {
        return number == null ? "" : " number=" + number;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

/**
 * What an overdue claim is charged: the sheet's late percent of its figure for every full 30 days it is overdue
 * (its due-by, its date plus the terms, before the sheet's today), rounded like a due. Never bound by a statement:
 * it follows the sheet's today until the claim is settled. A correction is never charged.
 */
public record LateCharge(int terms, BigDecimal pct, LocalDate today) {

    /** The days in each period an overdue claim is charged for. */
    public static final int PERIOD_DAYS = 30;

    /** The charge on the claim's figure (null: n/a, charged nothing); zero unless the claim is overdue. */
    public BigDecimal on(Claim claim, BigDecimal figure) {
        if (figure == null || claim.status() != ClaimStatus.OPEN || claim.correction()) {
            return BigDecimal.ZERO.setScale(2);
        }
        long late = ChronoUnit.DAYS.between(claim.date().plusDays(terms), today);
        long periods = late > 0 ? late / PERIOD_DAYS : 0;
        return Claim.due(figure, pct.multiply(BigDecimal.valueOf(periods)));
    }
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { counts } from '../claims/claims';
import type { Claim } from '../claims/claims';
import { latePeriods } from '../overdue/dueBy';
import { gradeOn } from '../people/people';
import type { GradeFrom } from '../people/people';
import { sheetKey, useCurrentSheet } from '../session/session';
import type { DueRules } from '../settings/settings';

/**
 * A grade's rate as the store holds it: a percent with two decimals, in force from its from-date
 * (yyyy-MM-dd; null: from the beginning of time) until the grade's next rate takes over.
 */
export type Rate = { grade: string; rate: string; from: string | null };

/** The fields the rate form submits; a blank from-date is from the beginning of time. */
export type RateInput = { grade: string; rate: string; from: string };

/** What a due shows when its grade has no rate. */
export const NA = 'n/a';

/** 0.00 or more, with at most two decimals. */
export const PERCENT = /^(\d{1,5}(\.\d{1,2})?|\.\d{1,2})$/;

/** The query key for the sheet's rates; under sheetKey, so re-loading the sheet re-reads them. */
export const ratesKey = (sheet: string) => [...sheetKey(sheet), 'rates'] as const;

/** The sheet's rates, by grade and then from-date (from the start first). */
export function useRates() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: ratesKey(sheet),
    queryFn: () => getJson<Rate[]>(`/api/sheets/${encodeURIComponent(sheet)}/rates`),
    enabled: !!sheet,
  });
}

/**
 * The grade's rate (two decimals) in force on the date: the one with the latest from-date on or
 * before it, a rate with no from-date applying from the start; undefined when none applies.
 */
export function rateFor(rates: Rate[], grade: string | undefined, date: string): string | undefined {
  let found: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (!found || (found.from ?? '') < (r.from ?? '')) found = r;
  }
  return found?.rate;
}

/** A two-decimal value as whole hundredths, exactly. */
const hundredths = (value: string) => Math.round(Number(value) * 100);

/**
 * An amount times a percent rate, divided by 100, rounded half to even to two decimals; n/a with no
 * rate. Worked in whole hundredths so it is exact: cents × basis points / 10000.
 */
export function due(amount: string, rate: string | undefined): string {
  if (rate === undefined) return NA;
  return percentOf(hundredths(amount), hundredths(rate));
}

/** Cents times basis points / 10000, rounded half to even to two decimals. */
function percentOf(amountCents: number, basisPoints: number): string {
  const product = amountCents * basisPoints;
  const whole = Math.floor(Math.abs(product) / 10000);
  const rest = Math.abs(product) - whole * 10000;
  const up = rest > 5000 || (rest === 5000 && whole % 2 === 1);
  const cents = Math.sign(product) * (whole + (up ? 1 : 0));
  return (cents / 100).toFixed(2);
}

/** A live due raised to the floor (both two decimals); n/a stays n/a. */
export function floored(value: string, floor: string): string {
  return value !== NA && hundredths(value) < hundredths(floor) ? Number(floor).toFixed(2) : value;
}

/**
 * A claim's figure: the figure its statement bound it to, else its amount at the rate in force on its
 * date for the person's grade in force on that date, at least the sheet's floor — a correction has no floor.
 */
function claimFigure(claim: Claim, rates: Rate[], grades: GradeFrom[], floor: string): string {
  if (claim.stated) return claim.statedDue ?? NA;
  const live = due(claim.amount, rateFor(rates, gradeOn(grades, claim.date), claim.date));
  return claim.corrects !== null ? live : floored(live, floor);
}

/**
 * The late charge on a figure: the late percent of it for every full 30 days the claim is overdue,
 * rounded like a due; 0.00 when it is not overdue, and always for a correction.
 */
export function lateCharge(claim: Claim, figure: string, rules: DueRules): string {
  if (claim.corrects !== null) return '0.00';
  const periods = latePeriods(claim, rules.terms, rules.today);
  return percentOf(hundredths(figure), hundredths(rules.latePct) * periods);
}

/**
 * A claim's due: the one fixed when it was settled (any late charge frozen in), else its figure plus
 * the late charge on it while it is overdue. The charge is never bound by a statement: it follows the
 * sheet's today.
 */
export function claimDue(claim: Claim, rates: Rate[], grades: GradeFrom[], rules: DueRules): string {
  if (claim.due !== null) return claim.due;
  const figure = claimFigure(claim, rates, grades, rules.floor);
  return figure === NA ? NA : total([figure, lateCharge(claim, figure, rules)]);
}

/** Whether a claim keeps a figure whatever the rates: fixed when settled, or bound by a statement. */
const keepsFigure = (c: Claim) => c.due !== null || (c.stated && c.statedDue !== null);

/**
 * A person's due-total: the figures of their claims that count, added up (0.00 with none). With no
 * rate in force on the sheet's today for their grade on that day it is n/a, unless a claim has a figure (kept
 * when settled or stated, or at the rate for the grade in force on its date): then it is the figures there are,
 * added up. While they are held, their open claims do not count.
 */
export function personDue(
  claims: Claim[],
  rates: Rate[],
  grades: GradeFrom[],
  held: boolean,
  rules: DueRules,
): string {
  const counted = claims.filter((c) => counts(c, held));
  const figures = counted.map((c) => claimDue(c, rates, grades, rules));
  const anyFigure = counted.some(keepsFigure) || figures.some((f) => f !== NA);
  if (rateFor(rates, gradeOn(grades, rules.today), rules.today) === undefined && !anyFigure) {
    return NA;
  }
  return total(figures);
}

/** Dues added up, skipping n/a; with two decimals, added in cents so it is exact. */
export function total(dues: string[]): string {
  const cents = dues.filter((d) => d !== NA).reduce((sum, d) => sum + hundredths(d), 0);
  return (cents / 100).toFixed(2);
}
