                continue;
            }
            BigDecimal figure = claim.due(Rate.inForce(sheetRates, person.gradeOn(claim.date()), claim.date()), floor, late);
            if (figure != null) {
                total = total.add(figure);
            }
        }
        closed.set(period.close(total));
    }
